  m JSONB;
  uid UUID;
  email_clean TEXT;
  designation_full TEXT;
  created_count INT := 0;
  updated_count INT := 0;
  failed_count INT := 0;
BEGIN
  -- Pass 1: Insert all DOs from Master DO file ──
  FOR m IN SELECT * FROM jsonb_array_elements(master_dos) LOOP
    BEGIN
      email_clean := LOWER(TRIM(m->>'email'));
      designation_full := 'DO - ' || (m->>'do_role');

      SELECT id INTO uid FROM auth.users WHERE LOWER(email) = email_clean;

      IF uid IS NULL THEN
        uid := uuid_generate_v4();
        INSERT INTO auth.users (
          id, aud, role, email, encrypted_password,
          email_confirmed_at, created_at, updated_at,
          raw_user_meta_data, raw_app_meta_data, is_super_admin, instance_id
        ) VALUES (
          uid, 'authenticated', 'authenticated',
          email_clean,
          crypt('Rotaract@3233', gen_salt('bf')),
          NOW(), NOW(), NOW(),
          jsonb_build_object('full_name', m->>'name'),
          '{}'::jsonb, false,
          '00000000-0000-0000-0000-000000000000'
        );
        created_count := created_count + 1;
      ELSE
        updated_count := updated_count + 1;
      END IF;

      UPDATE public.profiles
      SET full_name = m->>'name',
          designation = designation_full,
          club_name = m->>'club',
          phone_number = NULLIF(m->>'phone', ''),
          date_of_birth = NULLIF(m->>'dob', '')::DATE,
          address = NULLIF(m->>'address', ''),
          t_shirt_size = NULLIF(m->>'tshirt', ''),
          blood_group = NULLIF(m->>'blood', ''),
          willing_to_donate_blood = NULLIF(m->>'donate', '')
      WHERE id = uid;

      IF NOT FOUND THEN
        INSERT INTO public.profiles (id, email, full_name, role, designation, club_name, phone_number, date_of_birth, address, t_shirt_size, blood_group, willing_to_donate_blood)
        VALUES (uid, email_clean, m->>'name', 'member', designation_full, m->>'club',
                NULLIF(m->>'phone', ''),
                NULLIF(m->>'dob', '')::DATE,
                NULLIF(m->>'address', ''),
                NULLIF(m->>'tshirt', ''),
                NULLIF(m->>'blood', ''),
                NULLIF(m->>'donate', ''));
      END IF;

    EXCEPTION WHEN OTHERS THEN
      failed_count := failed_count + 1;
      RAISE NOTICE 'DO failed: % — %', m->>'email', SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '═══════════════════════════════════════════';
  RAISE NOTICE 'Master DO pass: created=%, updated=%, failed=%', created_count, updated_count, failed_count;
  RAISE NOTICE '═══════════════════════════════════════════';

  created_count := 0; updated_count := 0; failed_count := 0;

  -- Pass 2: Process Envision (Presidents/Secretaries) ──
  -- For overlapping emails, this OVERRIDES the DO designation ──
  FOR m IN SELECT * FROM jsonb_array_elements(envision_ps) LOOP
    BEGIN
      email_clean := LOWER(TRIM(m->>'email'));
      designation_full := m->>'role';  -- 'President' or 'Secretary'

      SELECT id INTO uid FROM auth.users WHERE LOWER(email) = email_clean;

      IF uid IS NULL THEN
        uid := uuid_generate_v4();
        INSERT INTO auth.users (
          id, aud, role, email, encrypted_password,
          email_confirmed_at, created_at, updated_at,
          raw_user_meta_data, raw_app_meta_data, is_super_admin, instance_id
        ) VALUES (
          uid, 'authenticated', 'authenticated',
          email_clean,
          crypt('Rotaract@3233', gen_salt('bf')),
          NOW(), NOW(), NOW(),
          jsonb_build_object('full_name', m->>'name'),
          '{}'::jsonb, false,
          '00000000-0000-0000-0000-000000000000'
        );
        created_count := created_count + 1;
      ELSE
        updated_count := updated_count + 1;
      END IF;

      UPDATE public.profiles
      SET full_name = m->>'name',
          designation = designation_full,
          club_name = m->>'club',
          phone_number = COALESCE(NULLIF(m->>'phone', ''), phone_number),
          t_shirt_size = COALESCE(NULLIF(m->>'tshirt', ''), t_shirt_size)
      WHERE id = uid;

      IF NOT FOUND THEN
        INSERT INTO public.profiles (id, email, full_name, role, designation, club_name, phone_number, t_shirt_size)
        VALUES (uid, email_clean, m->>'name', 'member', designation_full, m->>'club',
                NULLIF(m->>'phone', ''),
                NULLIF(m->>'tshirt', ''));
      END IF;

    EXCEPTION WHEN OTHERS THEN
      failed_count := failed_count + 1;
      RAISE NOTICE 'Envision failed: % — %', m->>'email', SQLERRM;
    END;
  END LOOP;

  RAISE NOTICE '═══════════════════════════════════════════';
  RAISE NOTICE 'Envision pass: created=%, updated=%, failed=%', created_count, updated_count, failed_count;
  RAISE NOTICE '═══════════════════════════════════════════';
END $$;

-- ── Verify ──
SELECT designation, COUNT(*) AS total
FROM public.profiles
GROUP BY designation
ORDER BY total DESC;
